'use strict';

// MODULES //

var copy = require( '@stdlib/array/base/copy' );
var format = require( '@stdlib/string/format' );
var axis = require( './axis.js' );


// VARIABLES //

var PREFIX = 'axes/';


// MAIN //

/**
* Returns a list of transformed axis schemas containing signals for use in conjunction with UI components.
*
* ## Notes
*
* -   The function mutates the provided list of signals.
*
* @private
* @param {Array<Object>} schema - list of axis schemas
* @param {Array} signals - list of signals
* @param {Object} defaults - axis schema defaults
* @returns {Array<Object>} transformed schemas
*/
function transform( schema, signals, defaults ) {
	var out;
	var i;

	out = copy( schema );
	for ( i = 0; i < out.length; i++ ) {
		out[ i ] = axis( schema[ i ], signals, defaults, format( '%s%d/', PREFIX, i ) );
	}
	return out;
}


// EXPORTS //

module.exports = transform;
